-- 세트 348: Service 손연습: expose, 엔드포인트와 EndpointSlice, 셀렉터·라벨, targetPort, 헤드리스, DNS 이름 호출
-- 명세: docs/specs/spec_k8s_service_set.md. 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (348, 1, 'Pod 하나를 expose 로 Service 에 연결하기', 'Pod `sv348-solo` 가 하나 떠 있고 `8080` 포트에서 응답합니다. 이 Pod 를 **`kubectl expose`** 로 노출하는 ClusterIP Service **`sv348-solo-svc`** 를 만들고 포트는 `8080` 으로 하세요. 만든 뒤 엔드포인트에 Pod 주소가 나타나야 해요.', '`kubectl expose` 는 Deployment 뿐 아니라 Pod 도 노출할 수 있어요. `kubectl expose --help` 에서 Service 이름과 포트를 정하는 옵션을 찾아 보세요. 대상 종류는 `pod` 이고, 셀렉터는 Pod 의 라벨에서 자동으로 가져옵니다.', 'kubectl expose pod sv348-solo --name=sv348-solo-svc --port=8080 -n $NS
kubectl get service sv348-solo-svc -n $NS -o wide
kubectl get endpoints sv348-solo-svc -n $NS

# expose 는 대상의 라벨을 셀렉터로 옮겨 Service 를 만든다 (Pod 는 run=이름 라벨)
# 라벨이 없는 Pod 는 expose 할 수 없다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab348 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service sv348-solo-svc sv348-web-svc sv348-count-svc sv348-blue-svc sv348-api-svc sv348-rd-svc sv348-hl-svc sv348-hl2-svc sv348-bg-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: sv348-solo\\n  labels:\\n    run: sv348-solo\\n    etude: lab348\\nspec:\\n  containers:\\n  - name: c\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo solo-348 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n    ports:\\n    - containerPort: 8080\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod -l etude=lab348 -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get service sv348-solo-svc -n $NS -o jsonpath=''{.spec.type}'' 2>/dev/null)\\" = \\"ClusterIP\\" ] ) && ( [ \\"$(kubectl get service sv348-solo-svc -n $NS -o jsonpath=''{.spec.ports[0].port}-{.spec.selector.run}'' 2>/dev/null)\\" = \\"8080-sv348-solo\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-solo-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"1\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Service sv348-solo-svc 가 ClusterIP 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-solo-svc -n $NS -o jsonpath=''{.spec.type}'' 2>/dev/null)\\" = \\"ClusterIP\\" ]"]}, {"label": "포트가 8080 이고 셀렉터가 Pod 의 라벨(run=sv348-solo)이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-solo-svc -n $NS -o jsonpath=''{.spec.ports[0].port}-{.spec.selector.run}'' 2>/dev/null)\\" = \\"8080-sv348-solo\\" ]"]}, {"label": "엔드포인트에 Pod 주소가 1개 연결되어 있다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-solo-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"1\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "서비스(Service)", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "kubectl expose", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_expose/"}, {"title": "EndpointSlice", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}, {"title": "서비스와 파드의 DNS", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}, {"title": "서비스로 애플리케이션 연결하기", "url": "https://kubernetes.io/docs/tutorials/services/connect-applications-service/"}]'),
  (348, 2, 'expose 로 받는 포트와 Pod 포트를 다르게 하기', 'Deployment `sv348-web`(복제본 2개)의 컨테이너는 `8080` 포트에서 응답합니다. 이를 **Service 는 `80` 포트로 받고 Pod 의 `8080` 으로 넘기도록** 노출하는 Service **`sv348-web-svc`** 를 `kubectl expose` 한 줄로 만드세요.', '`kubectl expose --help` 에 "Service 가 받는 포트" 와 "컨테이너로 보내는 포트" 를 각각 정하는 옵션이 있어요. 둘을 따로 주지 않으면 같은 번호가 됩니다.', 'kubectl expose deployment sv348-web --name=sv348-web-svc --port=80 --target-port=8080 -n $NS
kubectl get service sv348-web-svc -n $NS -o yaml | grep -E ''port|targetPort''
kubectl get endpoints sv348-web-svc -n $NS

# port 는 Service 가 받는 번호, targetPort 는 Pod 컨테이너가 듣는 번호다
# 엔드포인트에는 Service 포트(80)가 아니라 Pod 포트(8080)가 보인다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab348 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service sv348-solo-svc sv348-web-svc sv348-count-svc sv348-blue-svc sv348-api-svc sv348-rd-svc sv348-hl-svc sv348-hl2-svc sv348-bg-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: sv348-web\\n  labels:\\n    etude: lab348\\nspec:\\n  replicas: 2\\n  selector:\\n    matchLabels:\\n      app: sv348-web\\n      etude: lab348\\n  template:\\n    metadata:\\n      labels:\\n        app: sv348-web\\n        etude: lab348\\n    spec:\\n      containers:\\n      - name: c\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo web-348 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n        ports:\\n        - containerPort: 8080\\n---\\nEOF\\nkubectl rollout status deployment/sv348-web -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get service sv348-web-svc -n $NS -o jsonpath=''{.spec.ports[0].port}-{.spec.ports[0].targetPort}'' 2>/dev/null)\\" = \\"80-8080\\" ] ) && ( [ \\"$(kubectl get service sv348-web-svc -n $NS -o jsonpath=''{.spec.selector.app}'' 2>/dev/null)\\" = \\"sv348-web\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-web-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"2\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && [ \\"$(kubectl get endpoints sv348-web-svc -n $NS -o jsonpath=''{.subsets[0].ports[0].port}'' 2>/dev/null)\\" = \\"8080\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Service 포트 80, targetPort 8080 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-web-svc -n $NS -o jsonpath=''{.spec.ports[0].port}-{.spec.ports[0].targetPort}'' 2>/dev/null)\\" = \\"80-8080\\" ]"]}, {"label": "셀렉터가 Deployment 의 Pod 라벨(app=sv348-web)이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-web-svc -n $NS -o jsonpath=''{.spec.selector.app}'' 2>/dev/null)\\" = \\"sv348-web\\" ]"]}, {"label": "엔드포인트에 Pod 2개가 8080 포트로 연결되어 있다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-web-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"2\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && [ \\"$(kubectl get endpoints sv348-web-svc -n $NS -o jsonpath=''{.subsets[0].ports[0].port}'' 2>/dev/null)\\" = \\"8080\\" ]"]}]', '[{"title": "서비스(Service)", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "kubectl expose", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_expose/"}, {"title": "EndpointSlice", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}, {"title": "서비스와 파드의 DNS", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}, {"title": "서비스로 애플리케이션 연결하기", "url": "https://kubernetes.io/docs/tutorials/services/connect-applications-service/"}]'),
  (348, 3, 'EndpointSlice 로 연결된 Pod 개수 세기', 'Service `sv348-count-svc` 는 이름이 다른 Deployment 두 개(`sv348-count-a`, `sv348-count-b`)의 Pod 를 함께 골라 씁니다. **Service 가 지금 실제로 연결하고 있는 Pod 의 개수**를 **EndpointSlice** 에서 읽어 숫자만 `/tmp/count.txt` 에 저장하세요.', '`kubectl get endpointslices -l kubernetes.io/service-name=Service이름` 으로 그 Service 의 조각을 찾을 수 있어요. `-o jsonpath=''{.items[*].endpoints[*].addresses[*]}''` 로 주소만 뽑아 `wc -w` 로 세어 보세요.', 'kubectl get endpointslices -n $NS -l kubernetes.io/service-name=sv348-count-svc
kubectl get endpointslices -n $NS -l kubernetes.io/service-name=sv348-count-svc -o jsonpath=''{.items[*].endpoints[*].addresses[*]}'' | wc -w | tr -d '' '' > /tmp/count.txt
cat /tmp/count.txt   # 3

# EndpointSlice 는 Endpoints 의 확장판이다. Service 이름 라벨로 찾고, 읽기만 하는 작업이라 Service 는 바뀌지 않는다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab348 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service sv348-solo-svc sv348-web-svc sv348-count-svc sv348-blue-svc sv348-api-svc sv348-rd-svc sv348-hl-svc sv348-hl2-svc sv348-bg-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: sv348-count-a\\n  labels:\\n    etude: lab348\\nspec:\\n  replicas: 2\\n  selector:\\n    matchLabels:\\n      app: sv348-count\\n      part: a\\n      etude: lab348\\n  template:\\n    metadata:\\n      labels:\\n        app: sv348-count\\n        part: a\\n        etude: lab348\\n    spec:\\n      containers:\\n      - name: c\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo a > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n        ports:\\n        - containerPort: 8080\\n---\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: sv348-count-b\\n  labels:\\n    etude: lab348\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: sv348-count\\n      part: b\\n      etude: lab348\\n  template:\\n    metadata:\\n      labels:\\n        app: sv348-count\\n        part: b\\n        etude: lab348\\n    spec:\\n      containers:\\n      - name: c\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo b > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n        ports:\\n        - containerPort: 8080\\n---\\napiVersion: v1\\nkind: Service\\nmetadata:\\n  name: sv348-count-svc\\n  labels:\\n    etude: lab348\\nspec:\\n  selector:\\n    app: sv348-count\\n  ports:\\n  - port: 80\\n    targetPort: 8080\\n---\\nEOF\\nkubectl rollout status deployment/sv348-count-a -n $NS --timeout=90s >/dev/null 2>&1; kubectl rollout status deployment/sv348-count-b -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(tr -d ''[:space:]'' < /tmp/count.txt 2>/dev/null)\\" = \\"3\\" ] ) && ( [ \\"$(kubectl get service sv348-count-svc -n $NS -o jsonpath=''{.spec.selector.app}'' 2>/dev/null)\\" = \\"sv348-count\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일에 연결된 Pod 개수 3 만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(tr -d ''[:space:]'' < /tmp/count.txt 2>/dev/null)\\" = \\"3\\" ]"]}, {"label": "Service 는 그대로이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-count-svc -n $NS -o jsonpath=''{.spec.selector.app}'' 2>/dev/null)\\" = \\"sv348-count\\" ]"]}]', '[{"title": "서비스(Service)", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "kubectl expose", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_expose/"}, {"title": "EndpointSlice", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}, {"title": "서비스와 파드의 DNS", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}, {"title": "서비스로 애플리케이션 연결하기", "url": "https://kubernetes.io/docs/tutorials/services/connect-applications-service/"}]'),
  (348, 4, '엔드포인트가 비어 있을 때 Pod 라벨로 고치기', 'Service `sv348-blue-svc` 의 셀렉터는 `app=sv348-blue` 인데, Pod `sv348-bp1`, `sv348-bp2` 는 라벨을 `app=sv348-bleu` 로 잘못 달아서 엔드포인트가 **비어** 있습니다. **Service 는 건드리지 말고** Pod 의 라벨을 고쳐서 두 Pod 가 모두 연결되게 하세요.', '`kubectl get endpoints 이름` 이 비어 있는지, `kubectl get pods --show-labels` 로 라벨 글자가 맞는지 비교해 보세요. 이미 있는 라벨 값을 바꿀 때는 `kubectl label` 에 덮어쓰는 옵션이 필요해요.', 'kubectl get endpoints sv348-blue-svc -n $NS         # 주소가 없다
kubectl get pods -n $NS --show-labels               # bleu 로 오타
kubectl label pod sv348-bp1 sv348-bp2 app=sv348-blue --overwrite -n $NS
kubectl get endpoints sv348-blue-svc -n $NS

# 이미 있는 라벨 값을 바꾸려면 --overwrite 가 필요하다
# 라벨을 고치면 엔드포인트가 몇 초 안에 따라온다. 한쪽(Service 셀렉터)만 맞추면 되므로 어느 쪽을 고칠지는 상황이 정한다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab348 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service sv348-solo-svc sv348-web-svc sv348-count-svc sv348-blue-svc sv348-api-svc sv348-rd-svc sv348-hl-svc sv348-hl2-svc sv348-bg-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: sv348-bp1\\n  labels:\\n    app: sv348-bleu\\n    etude: lab348\\nspec:\\n  containers:\\n  - name: c\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo bp1 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n    ports:\\n    - containerPort: 8080\\n---\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: sv348-bp2\\n  labels:\\n    app: sv348-bleu\\n    etude: lab348\\nspec:\\n  containers:\\n  - name: c\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo bp2 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n    ports:\\n    - containerPort: 8080\\n---\\napiVersion: v1\\nkind: Service\\nmetadata:\\n  name: sv348-blue-svc\\n  labels:\\n    etude: lab348\\nspec:\\n  selector:\\n    app: sv348-blue\\n  ports:\\n  - port: 80\\n    targetPort: 8080\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod -l etude=lab348 -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get service sv348-blue-svc -n $NS -o jsonpath=''{.spec.selector.app}'' 2>/dev/null)\\" = \\"sv348-blue\\" ] ) && ( [ \\"$(kubectl get pod sv348-bp1 -n $NS -o jsonpath=''{.metadata.labels.app}'' 2>/dev/null)\\" = \\"sv348-blue\\" ] && [ \\"$(kubectl get pod sv348-bp2 -n $NS -o jsonpath=''{.metadata.labels.app}'' 2>/dev/null)\\" = \\"sv348-blue\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-blue-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"2\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Service 의 셀렉터는 app=sv348-blue 그대로이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-blue-svc -n $NS -o jsonpath=''{.spec.selector.app}'' 2>/dev/null)\\" = \\"sv348-blue\\" ]"]}, {"label": "두 Pod 의 라벨이 app=sv348-blue 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod sv348-bp1 -n $NS -o jsonpath=''{.metadata.labels.app}'' 2>/dev/null)\\" = \\"sv348-blue\\" ] && [ \\"$(kubectl get pod sv348-bp2 -n $NS -o jsonpath=''{.metadata.labels.app}'' 2>/dev/null)\\" = \\"sv348-blue\\" ]"]}, {"label": "엔드포인트에 Pod 2개가 연결되어 있다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-blue-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"2\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "서비스(Service)", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "kubectl expose", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_expose/"}, {"title": "EndpointSlice", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}, {"title": "서비스와 파드의 DNS", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}, {"title": "서비스로 애플리케이션 연결하기", "url": "https://kubernetes.io/docs/tutorials/services/connect-applications-service/"}]'),
  (348, 5, '클러스터 밖에서도 노드 포트로 열 Service 유형', 'Deployment `web` 을 **각 노드의 포트로 클러스터 밖에서도 접근**할 수 있게 노출하려고 합니다. 알맞은 값을 빈칸에 고르세요.', '`kubectl expose --help` 의 `--type` 설명을 보면 Service 유형 이름들이 나와요. 대소문자도 정확히 써야 합니다.', NULL, NULL, '[]', 'fill', '["NodePort", "ExposeNode", "HostPort", "PublicIP"]', NULL, '`--type=NodePort` 는 모든 노드의 같은 포트(기본 30000번대)를 열어 그 포트로 들어온 요청을 Service 로 넘깁니다. 기본값은 클러스터 안에서만 쓰는 `ClusterIP` 예요. `ExposeNode`, `PublicIP` 는 Service 유형 이름이 아니고, `HostPort` 는 Pod 스펙의 컨테이너 포트 옵션이라 `--type` 에 쓸 수 없습니다.', '[0]', 'kubectl expose deployment web --port=80 --type={0}', NULL, NULL),
  (348, 6, 'Running 인데 엔드포인트에서 빠진 Pod 를 들어오게 하기', 'Service `sv348-rd-svc` 뒤에 Pod `sv348-rd1`, `sv348-rd2` 가 있고 둘 다 `Running` 입니다. 그런데 엔드포인트에는 하나만 있어요. `sv348-rd2` 는 파일 `/tmp/ready` 가 생기기 전까지 준비되지 않는 Pod 입니다. **Pod 를 지우거나 Service 를 바꾸지 말고** `sv348-rd2` 를 준비시켜 엔드포인트에 두 Pod 가 모두 들어오게 하세요.', '`kubectl get pods` 의 READY 칸과 `kubectl get endpoints -o yaml` 의 `notReadyAddresses` 를 보세요. 준비 상태는 Pod 안에 `/tmp/ready` 가 있는지로 정해져요. 컨테이너 안에서 명령을 실행하는 `kubectl exec` 를 써 보세요. 프로브 주기 때문에 몇 초 걸릴 수 있어요.', 'kubectl get pods -n $NS                                   # sv348-rd2 는 0/1
kubectl get endpoints sv348-rd-svc -n $NS -o yaml | grep -A3 notReady
kubectl exec sv348-rd2 -n $NS -- touch /tmp/ready
kubectl get endpoints sv348-rd-svc -n $NS                   # 몇 초 뒤 두 주소

# Ready 가 아닌 Pod 는 Running 이어도 엔드포인트의 notReadyAddresses 에 있어 트래픽을 받지 못한다
# readinessProbe 주기(2초)만큼 기다려야 바뀐다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab348 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service sv348-solo-svc sv348-web-svc sv348-count-svc sv348-blue-svc sv348-api-svc sv348-rd-svc sv348-hl-svc sv348-hl2-svc sv348-bg-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: sv348-rd1\\n  labels:\\n    app: sv348-rd\\n    etude: lab348\\nspec:\\n  containers:\\n  - name: c\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo rd1 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n    ports:\\n    - containerPort: 8080\\n    readinessProbe:\\n      exec:\\n        command: [\\"cat\\", \\"/tmp/ready\\"]\\n      initialDelaySeconds: 1\\n      periodSeconds: 2\\n---\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: sv348-rd2\\n  labels:\\n    app: sv348-rd\\n    etude: lab348\\nspec:\\n  containers:\\n  - name: c\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo rd2 > /www/index.html; exec httpd -f -p 8080 -h /www\\"]\\n    ports:\\n    - containerPort: 8080\\n    readinessProbe:\\n      exec:\\n        command: [\\"cat\\", \\"/tmp/ready\\"]\\n      initialDelaySeconds: 1\\n      periodSeconds: 2\\n---\\napiVersion: v1\\nkind: Service\\nmetadata:\\n  name: sv348-rd-svc\\n  labels:\\n    etude: lab348\\nspec:\\n  selector:\\n    app: sv348-rd\\n  ports:\\n  - port: 80\\n    targetPort: 8080\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod -l etude=lab348 -n $NS --timeout=90s >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/sv348-rd1 -n $NS --timeout=60s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get service sv348-rd-svc -n $NS -o jsonpath=''{.spec.selector.app}'' 2>/dev/null)\\" = \\"sv348-rd\\" ] && [ \\"$(kubectl get pod sv348-rd2 -n $NS -o jsonpath=''{.status.containerStatuses[0].restartCount}'' 2>/dev/null)\\" = \\"0\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get pod sv348-rd2 -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = \\"true\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-rd-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"2\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Service 는 그대로이고 Pod 를 새로 만들지 않았다 (재시작 0)", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-rd-svc -n $NS -o jsonpath=''{.spec.selector.app}'' 2>/dev/null)\\" = \\"sv348-rd\\" ] && [ \\"$(kubectl get pod sv348-rd2 -n $NS -o jsonpath=''{.status.containerStatuses[0].restartCount}'' 2>/dev/null)\\" = \\"0\\" ]"]}, {"label": "sv348-rd2 가 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get pod sv348-rd2 -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = \\"true\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "엔드포인트에 Ready 주소가 2개 있다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-rd-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"2\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "서비스(Service)", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "kubectl expose", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_expose/"}, {"title": "EndpointSlice", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}, {"title": "서비스와 파드의 DNS", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}, {"title": "서비스로 애플리케이션 연결하기", "url": "https://kubernetes.io/docs/tutorials/services/connect-applications-service/"}]'),
  (348, 7, 'NodePort Service 에서 세 포트는 어떻게 이어질까', 'Service 에 `port: 80`, `targetPort: 8080`, `nodePort: 31000` 이 정해져 있습니다. 클러스터 밖에서 노드 주소로 접근했을 때 요청이 가는 길로 알맞은 것은 무엇일까요?', '`nodePort` 는 노드가 여는 포트, `port` 는 Service 가 받는 포트, `targetPort` 는 Pod 컨테이너가 듣는 포트예요. 요청이 밖에서 안으로 지나가는 순서대로 이어 보세요.', NULL, NULL, '[]', 'choice', '["노드의 31000 포트로 들어온 요청이 Service 를 거쳐 Pod 의 8080 포트로 전달된다", "노드의 80 포트로 들어온 요청이 Service 를 거쳐 Pod 의 31000 포트로 전달된다", "노드의 8080 포트로 들어온 요청이 Service 를 거쳐 Pod 의 80 포트로 전달된다", "노드의 31000 포트로 들어온 요청이 Service 를 거쳐 Pod 의 80 포트로 전달된다"]', 0, '`nodePort` 는 노드가 여는 포트라 밖에서는 노드의 31000 으로 들어옵니다. 요청은 Service 를 지나 `targetPort` 인 Pod 의 8080 으로 가요. `port: 80` 은 클러스터 안에서 Service 이름으로 부를 때 쓰는 번호입니다. 노드의 80 이나 8080 을 여는 것도, Pod 의 31000 이나 80 으로 보내는 것도 이 설정에는 없는 길이에요.', NULL, NULL, NULL, NULL),
  (348, 8, 'Service 이름으로 임시 Pod 에서 호출해 응답 저장하기', 'Deployment `sv348-api`(Pod 2개)와 Service `sv348-api-svc`(포트 `80`)가 있습니다. **`kubectl run` 으로 일회용 busybox Pod 를 띄워** Service **이름**으로 호출하고, 받은 응답을 `/tmp/resp.txt` 에 저장하세요. 일회용 Pod 는 호출이 끝나면 남지 않아야 해요.', '`kubectl run 이름 --image=busybox:1.36 --rm -i --restart=Never -- 명령` 은 명령이 끝나면 Pod 를 지워 줘요. 안에서는 `wget -qO- http://Service이름` 으로 본문을 출력할 수 있고, 그 출력을 `>` 로 파일에 담으면 됩니다.', 'kubectl run sv348-tmp --image=busybox:1.36 --rm -i --restart=Never -n $NS -- wget -qO- http://sv348-api-svc > /tmp/resp.txt
cat /tmp/resp.txt
kubectl get pods -n $NS    # sv348-tmp 는 없다

# 같은 네임스페이스에서는 Service 이름만으로 DNS 가 풀린다
# --rm 은 -i 와 --restart=Never 와 함께 써야 동작한다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab348 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service sv348-solo-svc sv348-web-svc sv348-count-svc sv348-blue-svc sv348-api-svc sv348-rd-svc sv348-hl-svc sv348-hl2-svc sv348-bg-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: sv348-api\\n  labels:\\n    etude: lab348\\nspec:\\n  replicas: 2\\n  selector:\\n    matchLabels:\\n      app: sv348-api\\n      etude: lab348\\n  template:\\n    metadata:\\n      labels:\\n        app: sv348-api\\n        etude: lab348\\n    spec:\\n      containers:\\n      - name: c\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo api-ready-348 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n        ports:\\n        - containerPort: 8080\\n---\\napiVersion: v1\\nkind: Service\\nmetadata:\\n  name: sv348-api-svc\\n  labels:\\n    etude: lab348\\nspec:\\n  selector:\\n    app: sv348-api\\n  ports:\\n  - port: 80\\n    targetPort: 8080\\n---\\nEOF\\nkubectl rollout status deployment/sv348-api -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -Eq ''api-ready-348'' /tmp/resp.txt ) && ( ( i=0; while [ $i -lt 20 ]; do if [ \\"$(kubectl get pods -n $NS --no-headers 2>/dev/null | grep -vc sv348-api)\\" = \\"0\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일에 Service 가 돌려준 응답이 있다", "cmd": ["sh", "-c", "grep -Eq ''api-ready-348'' /tmp/resp.txt"]}, {"label": "일회용 Pod 가 남아 있지 않다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 20 ]; do if [ \\"$(kubectl get pods -n $NS --no-headers 2>/dev/null | grep -vc sv348-api)\\" = \\"0\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "서비스(Service)", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "kubectl expose", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_expose/"}, {"title": "EndpointSlice", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}, {"title": "서비스와 파드의 DNS", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}, {"title": "서비스로 애플리케이션 연결하기", "url": "https://kubernetes.io/docs/tutorials/services/connect-applications-service/"}]'),
  (348, 9, 'expose 로 헤드리스 Service 만들기', 'Deployment `sv348-hl-app`(복제본 3개, 포트 `8080`) 앞에 **헤드리스(Headless) Service `sv348-hl-svc`** 를 `kubectl expose` 로 만드세요. 포트는 `8080` 이고, 클러스터 IP 는 **없어야** 합니다. 엔드포인트에는 Pod 3개가 보여야 해요.', '헤드리스는 Service 의 `clusterIP` 를 `None` 으로 둔 것이에요. `kubectl expose --help` 에서 클러스터 IP 를 정하는 옵션을 찾아 보세요.', 'kubectl expose deployment sv348-hl-app --name=sv348-hl-svc --cluster-ip=None --port=8080 -n $NS
kubectl get service sv348-hl-svc -n $NS   # CLUSTER-IP 가 None
kubectl get endpoints sv348-hl-svc -n $NS

# 헤드리스는 가상 IP 없이, DNS 가 Pod IP 들을 직접 돌려준다
# 클러스터 IP 는 한 번 만든 뒤에는 바꿀 수 없어서 처음부터 None 으로 만든다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab348 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service sv348-solo-svc sv348-web-svc sv348-count-svc sv348-blue-svc sv348-api-svc sv348-rd-svc sv348-hl-svc sv348-hl2-svc sv348-bg-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: sv348-hl-app\\n  labels:\\n    etude: lab348\\nspec:\\n  replicas: 3\\n  selector:\\n    matchLabels:\\n      app: sv348-hl\\n      etude: lab348\\n  template:\\n    metadata:\\n      labels:\\n        app: sv348-hl\\n        etude: lab348\\n    spec:\\n      containers:\\n      - name: c\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo hl-348 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n        ports:\\n        - containerPort: 8080\\n---\\nEOF\\nkubectl rollout status deployment/sv348-hl-app -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get service sv348-hl-svc -n $NS -o jsonpath=''{.spec.clusterIP}'' 2>/dev/null)\\" = \\"None\\" ] ) && ( [ \\"$(kubectl get service sv348-hl-svc -n $NS -o jsonpath=''{.spec.selector.app}-{.spec.ports[0].port}'' 2>/dev/null)\\" = \\"sv348-hl-8080\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-hl-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"3\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "clusterIP 가 None 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-hl-svc -n $NS -o jsonpath=''{.spec.clusterIP}'' 2>/dev/null)\\" = \\"None\\" ]"]}, {"label": "셀렉터가 app=sv348-hl 이고 포트가 8080 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-hl-svc -n $NS -o jsonpath=''{.spec.selector.app}-{.spec.ports[0].port}'' 2>/dev/null)\\" = \\"sv348-hl-8080\\" ]"]}, {"label": "엔드포인트에 Pod 3개가 연결되어 있다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get endpoints sv348-hl-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | wc -w | tr -d \\" \\")\\" = \\"3\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "서비스(Service)", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "kubectl expose", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_expose/"}, {"title": "EndpointSlice", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}, {"title": "서비스와 파드의 DNS", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}, {"title": "서비스로 애플리케이션 연결하기", "url": "https://kubernetes.io/docs/tutorials/services/connect-applications-service/"}]'),
  (348, 10, '헤드리스 Service 의 DNS 는 Pod IP 를 모두 돌려준다', '헤드리스 Service `sv348-hl2-svc` 뒤에 Pod 3개가 있습니다. **일회용 busybox Pod** 에서 `nslookup` 으로 이 Service 이름을 조회하고, 그 결과 전체를 `/tmp/lookup.txt` 에 저장하세요. (결과에 Pod 3개의 주소가 모두 보여야 해요.)', '`kubectl run 이름 --image=busybox:1.36 --rm -i --restart=Never -- nslookup Service이름` 을 쓰고 출력을 `>` 로 파일에 담으세요. 일반 Service 는 주소 하나를 돌려주지만 헤드리스는 어떨지 비교해 보세요.', 'kubectl run sv348-dns --image=busybox:1.36 --rm -i --restart=Never -n $NS -- nslookup sv348-hl2-svc > /tmp/lookup.txt
cat /tmp/lookup.txt
kubectl get pods -n $NS -l app=sv348-hl2 -o wide   # 주소와 맞춰 보기

# 일반 Service 는 ClusterIP 하나, 헤드리스는 Ready 인 Pod IP 전부가 나온다
# 클라이언트가 직접 골라 연결하거나 StatefulSet 의 Pod 를 하나씩 찾을 때 쓴다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab348 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service sv348-solo-svc sv348-web-svc sv348-count-svc sv348-blue-svc sv348-api-svc sv348-rd-svc sv348-hl-svc sv348-hl2-svc sv348-bg-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: sv348-hl2-app\\n  labels:\\n    etude: lab348\\nspec:\\n  replicas: 3\\n  selector:\\n    matchLabels:\\n      app: sv348-hl2\\n      etude: lab348\\n  template:\\n    metadata:\\n      labels:\\n        app: sv348-hl2\\n        etude: lab348\\n    spec:\\n      containers:\\n      - name: c\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo hl2 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n        ports:\\n        - containerPort: 8080\\n---\\napiVersion: v1\\nkind: Service\\nmetadata:\\n  name: sv348-hl2-svc\\n  labels:\\n    etude: lab348\\nspec:\\n  clusterIP: None\\n  selector:\\n    app: sv348-hl2\\n  ports:\\n  - port: 8080\\n    targetPort: 8080\\n---\\nEOF\\nkubectl rollout status deployment/sv348-hl2-app -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get pods -n $NS -l app=sv348-hl2 --no-headers 2>/dev/null | wc -l | tr -d '' '')\\" = \\"3\\" ] ) && ( f=/tmp/lookup.txt; [ -s $f ] && for ip in $(kubectl get pods -n $NS -l app=sv348-hl2 -o jsonpath=''{.items[*].status.podIP}''); do grep -q \\"$ip\\" $f || exit 1; done ) && ( grep -Eq ''sv348-hl2-svc'' /tmp/lookup.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Pod 가 3개 떠 있다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pods -n $NS -l app=sv348-hl2 --no-headers 2>/dev/null | wc -l | tr -d '' '')\\" = \\"3\\" ]"]}, {"label": "조회 결과에 Pod 3개의 주소가 모두 있다", "cmd": ["sh", "-c", "f=/tmp/lookup.txt; [ -s $f ] && for ip in $(kubectl get pods -n $NS -l app=sv348-hl2 -o jsonpath=''{.items[*].status.podIP}''); do grep -q \\"$ip\\" $f || exit 1; done"]}, {"label": "조회한 Service 이름이 결과에 있다", "cmd": ["sh", "-c", "grep -Eq ''sv348-hl2-svc'' /tmp/lookup.txt"]}]', '[{"title": "서비스(Service)", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "kubectl expose", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_expose/"}, {"title": "EndpointSlice", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}, {"title": "서비스와 파드의 DNS", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}, {"title": "서비스로 애플리케이션 연결하기", "url": "https://kubernetes.io/docs/tutorials/services/connect-applications-service/"}]'),
  (348, 11, 'Service 셀렉터를 바꿔 새 버전으로 넘기고 확인하기', 'Service `sv348-bg-svc` 는 지금 `version=v1` Pod(Deployment `sv348-v1`)에 연결되어 있습니다. 새 버전 Deployment `sv348-v2`(`version=v2`)도 떠 있어요. **Service 가 `v2` Pod 로만 연결되도록** 바꾸고, **일회용 Pod 에서 Service 이름으로 호출한 응답**을 `/tmp/after.txt` 에 저장해 `v2` 의 응답임을 확인하세요.', '`kubectl get service 이름 -o yaml` 로 셀렉터를 보고 `kubectl patch` 로 `spec.selector` 의 `version` 값을 바꿔요. 엔드포인트가 따라오는 데 잠깐 걸리니 바꾼 직후에 호출했는데 옛 응답이 오면 다시 호출하세요.', 'kubectl patch service sv348-bg-svc -n $NS -p ''{"spec":{"selector":{"version":"v2"}}}''
kubectl get endpoints sv348-bg-svc -n $NS
kubectl run sv348-tmp --image=busybox:1.36 --rm -i --restart=Never -n $NS -- wget -qO- http://sv348-bg-svc > /tmp/after.txt
cat /tmp/after.txt

# 셀렉터만 바꾸면 Pod 는 그대로이고 트래픽만 옮겨 간다 (블루/그린 전환)
# patch 는 적은 키만 바꾸므로 app 라벨 조건은 남는다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab348 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service sv348-solo-svc sv348-web-svc sv348-count-svc sv348-blue-svc sv348-api-svc sv348-rd-svc sv348-hl-svc sv348-hl2-svc sv348-bg-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: sv348-v1\\n  labels:\\n    etude: lab348\\nspec:\\n  replicas: 2\\n  selector:\\n    matchLabels:\\n      app: sv348-bg\\n      version: v1\\n      etude: lab348\\n  template:\\n    metadata:\\n      labels:\\n        app: sv348-bg\\n        version: v1\\n        etude: lab348\\n    spec:\\n      containers:\\n      - name: c\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo version-1 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n        ports:\\n        - containerPort: 8080\\n---\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: sv348-v2\\n  labels:\\n    etude: lab348\\nspec:\\n  replicas: 2\\n  selector:\\n    matchLabels:\\n      app: sv348-bg\\n      version: v2\\n      etude: lab348\\n  template:\\n    metadata:\\n      labels:\\n        app: sv348-bg\\n        version: v2\\n        etude: lab348\\n    spec:\\n      containers:\\n      - name: c\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"mkdir -p /www; echo version-2 > /www/index.html; touch /tmp/ready; exec httpd -f -p 8080 -h /www\\"]\\n        ports:\\n        - containerPort: 8080\\n---\\napiVersion: v1\\nkind: Service\\nmetadata:\\n  name: sv348-bg-svc\\n  labels:\\n    etude: lab348\\nspec:\\n  selector:\\n    app: sv348-bg\\n    version: v1\\n  ports:\\n  - port: 80\\n    targetPort: 8080\\n---\\nEOF\\nkubectl rollout status deployment/sv348-v1 -n $NS --timeout=90s >/dev/null 2>&1; kubectl rollout status deployment/sv348-v2 -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get service sv348-bg-svc -n $NS -o jsonpath=''{.spec.selector.app}-{.spec.selector.version}'' 2>/dev/null)\\" = \\"sv348-bg-v2\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do if [ -n \\"$(kubectl get endpoints sv348-bg-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null)\\" ] && [ \\"$(kubectl get endpoints sv348-bg-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | tr \\" \\" \\"\\\\n\\" | sort)\\" = \\"$(kubectl get pods -n $NS -l version=v2 -o jsonpath=''{.items[*].status.podIP}'' | tr \\" \\" \\"\\\\n\\" | sort)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( grep -Eq ''version-2'' /tmp/after.txt && ! grep -Eq ''version-1'' /tmp/after.txt ) && ( ( i=0; while [ $i -lt 20 ]; do if [ \\"$(kubectl get pods -n $NS --no-headers 2>/dev/null | grep -vc sv348-v)\\" = \\"0\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "셀렉터가 app=sv348-bg 와 version=v2 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service sv348-bg-svc -n $NS -o jsonpath=''{.spec.selector.app}-{.spec.selector.version}'' 2>/dev/null)\\" = \\"sv348-bg-v2\\" ]"]}, {"label": "엔드포인트 주소가 v2 Pod 의 IP 와 같다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do if [ -n \\"$(kubectl get endpoints sv348-bg-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null)\\" ] && [ \\"$(kubectl get endpoints sv348-bg-svc -n $NS -o jsonpath=''{.subsets[*].addresses[*].ip}'' 2>/dev/null | tr \\" \\" \\"\\\\n\\" | sort)\\" = \\"$(kubectl get pods -n $NS -l version=v2 -o jsonpath=''{.items[*].status.podIP}'' | tr \\" \\" \\"\\\\n\\" | sort)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "저장한 응답이 v2 의 것이다", "cmd": ["sh", "-c", "grep -Eq ''version-2'' /tmp/after.txt && ! grep -Eq ''version-1'' /tmp/after.txt"]}, {"label": "일회용 Pod 가 남아 있지 않다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 20 ]; do if [ \\"$(kubectl get pods -n $NS --no-headers 2>/dev/null | grep -vc sv348-v)\\" = \\"0\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "서비스(Service)", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "kubectl expose", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_expose/"}, {"title": "EndpointSlice", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}, {"title": "서비스와 파드의 DNS", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}, {"title": "서비스로 애플리케이션 연결하기", "url": "https://kubernetes.io/docs/tutorials/services/connect-applications-service/"}]'),
  (348, 12, 'Service 로 연결이 안 될 때 살펴보는 순서', 'Service 로 접속이 안 될 때 원인을 찾고 고친 뒤 확인하는 순서대로 놓아 보세요.', '먼저 Service 가 무엇을 찾는지 읽고, 실제로 연결된 Pod 가 있는지 보고, 라벨을 비교한 뒤, 고치고, 마지막에 호출해 확인합니다.', NULL, NULL, '[]', 'order', '["틀린 쪽(Pod 라벨 또는 Service 셀렉터)을 고친다", "`kubectl get endpoints` 로 연결된 Pod 주소가 비었는지 본다", "임시 Pod 에서 Service 이름으로 `wget` 을 해 응답을 확인한다", "`kubectl get service` 로 셀렉터와 port, targetPort 를 읽는다", "`kubectl get pods --show-labels` 로 Pod 라벨이 셀렉터와 맞는지 비교한다"]', NULL, '먼저 `get service` 로 Service 가 어떤 라벨을, 어떤 포트로 찾는지 읽습니다. 그다음 `get endpoints` 가 비었는지 보면 "Pod 를 못 찾는지" 와 "찾았는데 포트가 틀린지" 가 갈려요. 비어 있으면 `get pods --show-labels` 로 라벨을 셀렉터와 비교하고, 틀린 쪽을 고친 뒤, 임시 Pod 에서 이름으로 호출해 실제로 응답이 오는지 확인합니다. 고치기 전에 호출부터 하면 어디가 문제인지 알 수 없어요.', '[3, 1, 4, 0, 2]', NULL, NULL, NULL);
